"use strict";

// Keep Django's native form errors and label associations, with a shared clickable
// label for checkbox fields generated by form.as_p.
document.querySelectorAll("form p > input[type='checkbox']").forEach((input) => {
  const label = input.parentElement.querySelector(`label[for="${input.id}"]`);
  if (label) {
    label.classList.add("check-label");
    label.prepend(input);
  }
});

// Source edits stay in this page until explicitly saved. Do not let another
// action submit an older source revision or discard a corrected transcript.
const draftForms = [];
const formValue = (form) => JSON.stringify([...new FormData(form)].filter(([key]) => key !== "csrfmiddlewaretoken"));
const draftBaselines = new WeakMap();
const dirtyForms = () => draftForms.filter((form) => form.isConnected && formValue(form) !== draftBaselines.get(form));
// Multiple edited forms need an explicit way out without silently choosing which
// draft to lose. Undo is reversible in memory until this page is left.
const initializeDraftForms = (root = document) => root.querySelectorAll("form[data-unsaved-form]").forEach((form) => {
  if (draftBaselines.has(form)) return;
  draftForms.push(form);
  draftBaselines.set(form, formValue(form));
  let undone = null;
  const undo = document.createElement("button");
  undo.type = "button";
  undo.className = "quiet";
  undo.dataset.undoEdits = "true";
  undo.hidden = true;
  const help = document.createElement("p");
  help.className = "helptext";
  help.hidden = true;
  const refresh = () => {
    const dirty = formValue(form) !== draftBaselines.get(form);
    undo.hidden = !dirty && !undone;
    undo.textContent = dirty ? "Undo these unsaved edits" : "Restore undone edits";
    help.hidden = !undone || dirty;
    help.textContent = "Saved values restored for this form. You can restore the undone edits until you leave this page.";
  };
  undo.addEventListener("click", () => {
    if (formValue(form) !== draftBaselines.get(form)) {
      undone = [...form.elements].filter((element) => element.name && element.type !== "file")
        .map((element) => ({element, value: element.value, checked: element.checked}));
      form.reset();
    } else if (undone) {
      undone.forEach(({element, value, checked}) => {element.value = value; if (typeof checked === "boolean") element.checked = checked;});
      undone = null;
    }
    form.dispatchEvent(new Event("input", {bubbles:true}));
    refresh();
  });
  form.addEventListener("input", refresh);
  form.addEventListener("change", refresh);
  form.append(undo, help);
});
initializeDraftForms();
let pageSubmission = false;
let audioUnsaved = false;
let audioBusy = false;
const notesForm = document.querySelector("[data-notes-form]");
const notesStatus = document.querySelector("[data-notes-status]");
const generationStatus = document.querySelector("[data-generation-status]");
if (notesForm) notesForm.addEventListener("input", () => {
  const dirty = dirtyForms().includes(notesForm);
  notesStatus.textContent = dirty ? "Unsaved notes. Save before generating or transcribing." : "Notes match the saved revision.";
  if (generationStatus) generationStatus.textContent = dirty ? "Save your current notes before generating answers." : "";
});
document.addEventListener("submit", (event) => {
  const form = event.target;
  const unsaved = dirtyForms().find((other) => other !== form);
  const voice = form.matches("[data-voice-form]");
  if (unsaved || audioBusy || (audioUnsaved && !voice)) {
    event.preventDefault();
    event.stopImmediatePropagation();
    const target = unsaved?.querySelector("textarea, input, select") || document.querySelector("[data-voice-record]");
    target?.focus();
    const message = unsaved ? "Save or undo the unsaved edits in the other form before using this action." : audioBusy ? "Stop or discard the recording before continuing." : "Transcribe or discard the selected recording before using another action.";
    if (generationStatus) generationStatus.textContent = message;
    if (notesStatus) notesStatus.textContent = message;
  }
}, true);
window.addEventListener("beforeunload", (event) => {
  if (!pageSubmission && (dirtyForms().length || audioUnsaved || audioBusy)) {
    event.preventDefault();
    event.returnValue = "";
  }
});
// Run after each form's own validation/recording guard.
document.addEventListener("submit", (event) => { if (!event.defaultPrevented) pageSubmission = true; });

// Preserve native validation and form field submission while limiting accidental
// repeated clicks. The server remains responsible for idempotency.
const initializedSubmissions = new WeakSet();
const submissionTimers = new WeakMap();
const resetSubmission = (form) => {
  clearTimeout(submissionTimers.get(form));
  submissionTimers.delete(form);
  delete form.dataset.submitting;
  form.querySelectorAll("[data-original-label]").forEach((button) => {
    button.textContent = button.dataset.originalLabel;
    button.removeAttribute("aria-disabled");
    delete button.dataset.originalLabel;
  });
  form.querySelector("[data-submission-recovery]")?.remove();
};
const initializeSubmitOnceForms = (root = document) => root.querySelectorAll("form[data-submit-once]").forEach((form) => {
  if (initializedSubmissions.has(form)) return;
  initializedSubmissions.add(form);
  form.addEventListener("submit", (event) => {
    if (event.defaultPrevented) return;
    if (form.dataset.submitting) {
      event.preventDefault();
      return;
    }
    form.dataset.submitting = "true";
    const button = event.submitter;
    // Other form guards run later in the same event. Their cancellation is not
    // a submitted request and must not leave this native-navigation guard set.
    // A task (not a microtask) runs after every submit listener: browsers may
    // run a microtask checkpoint between separate listener callbacks.
    setTimeout(() => {
      if (event.defaultPrevented) {
        delete form.dataset.submitting;
        pageSubmission = false;
        return;
      }
      if (button) {
        button.dataset.originalLabel = button.textContent;
        button.setAttribute("aria-disabled", "true");
        button.textContent = button.dataset.pendingLabel || "Working…";
      }
      // Native navigation has no reliable failed-request event: a browser
      // inspector can block it, or the response can be lost after a commit.
      // Never infer failure or repeat its POST. Keep this draft and offer a
      // separate GET of the current page to inspect the saved result instead.
      submissionTimers.set(form, setTimeout(() => {
        if (!form.isConnected || form.dataset.submitting !== "true") return;
        form.dataset.submitting = "uncertain";
        pageSubmission = false;
        if (button) button.textContent = "Save result unconfirmed";
        const recovery = document.createElement("div");
        recovery.className = "notice warning";
        recovery.dataset.submissionRecovery = "true";
        recovery.setAttribute("role", "status");
        const explanation = document.createElement("p");
        explanation.textContent = "The save result has not been confirmed. Your entries are kept here. Check the saved page before trying this action again; the original request may still complete.";
        const link = document.createElement("a");
        link.href = location.href;
        link.target = "_blank";
        link.rel = "noopener";
        link.textContent = "Check saved page in a new tab";
        recovery.append(explanation, link);
        form.append(recovery);
      }, 15000));
    }, 0);
  });
});
initializeSubmitOnceForms();
// A newly returned review form receives the same unsaved-edit and submit guards
// as the original page. Expose only a read of dirty state, never draft contents.
window.quillmdFormState = Object.freeze({
  hasUnsavedEdits: (root = document) => dirtyForms().some((form) => root.contains(form))
});
document.addEventListener("quillmd:content-updated", (event) => {
  const root = event.detail?.root;
  if (!(root instanceof Element)) return;
  initializeDraftForms(root);
  initializeSubmitOnceForms(root);
});

// A back/forward restore must retain the doctor's edits. The server still
// rejects stale revisions/quotes; reset only the completed submission UI.
window.addEventListener("pageshow", (event) => {
  if (!event.persisted) return;
  pageSubmission = false;
  document.querySelectorAll("form[data-submit-once]").forEach((form) => {
    resetSubmission(form);
  });
});

// Question labels are editable without exposing JSON. Keep the server-rendered
// form usable when JavaScript is unavailable or a validation response is invalid.
document.querySelectorAll("form[data-mapping-form]").forEach((form) => {
  const original = form.querySelector("textarea[name='labels']");
  const editor = form.querySelector("[data-mapping-editor]");
  if (!original || !editor) return;
  try {
    const labels = JSON.parse(original.value);
    if (!labels || Array.isArray(labels) || typeof labels !== "object") return;
    // Where each blank sits in the original form. "Question 1, Question 2, ..." asked the
    // doctor to confirm a label without saying WHICH blank it names, which is the one thing
    // this screen exists to establish. Absent or short: fall back, never mislabel.
    let locations = [];
    const carrier = document.getElementById("mapping-locations");
    if (carrier) {
      try {
        const parsed = JSON.parse(carrier.textContent);
        if (Array.isArray(parsed)) locations = parsed;
      } catch (_) {
        locations = [];
      }
    }
    Object.entries(labels).forEach(([key, value], index) => {
      const wrapper = document.createElement("p");
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.id = `mapping-label-${index}`;
      input.value = value;
      input.maxLength = 300;
      input.required = true;
      label.htmlFor = input.id;
      label.textContent = typeof locations[index] === "string" && locations[index]
        ? `Question ${index + 1} — ${locations[index]}`
        : `Question ${index + 1}`;
      input.addEventListener("input", () => {
        labels[key] = input.value;
        original.value = JSON.stringify(labels);
      });
      wrapper.append(label, input);
      editor.append(wrapper);
    });
    form.querySelector("[data-mapping-json]").hidden = true;
  } catch (_) {
    // Retain Django's original form and validation feedback.
  }
});

document.querySelectorAll("form[data-voice-form]").forEach((form) => {
  const start = form.querySelector("[data-voice-record]");
  const stop = form.querySelector("[data-voice-stop]");
  const discard = form.querySelector("[data-voice-discard]");
  const status = form.querySelector("[data-voice-status]");
  const preview = form.querySelector("[data-voice-preview]");
  const fileInput = form.querySelector("input[type=file]");
  if (!start || !stop || !discard || !status || !fileInput) return;
  let recorder, recordingStream, stopTimer, audioUrl;
  let generation = 0;
  let recordingFailed = false;
  let reachedLimit = false;
  const release = () => {
    recordingStream?.getTracks().forEach((track) => track.stop());
    recordingStream = null;
    clearTimeout(stopTimer);
    audioBusy = false;
    start.disabled = !capable;
    fileInput.disabled = false;
    stop.disabled = true;
  };
  const previewFile = (file) => {
    if (audioUrl) URL.revokeObjectURL(audioUrl);
    audioUrl = file ? URL.createObjectURL(file) : null;
    preview.hidden = !file;
    if (file) preview.src = audioUrl; else preview.removeAttribute("src");
    audioUnsaved = Boolean(file);
    discard.disabled = !file;
  };
  const clearRecording = () => {
    generation += 1;
    recordingFailed = true;
    if (recorder?.state === "recording") recorder.stop();
    release();
    fileInput.value = "";
    previewFile(null);
    const consent = form.querySelector("input[name=consent]");
    if (consent) consent.checked = false;
    status.textContent = "Recording discarded. Nothing was sent.";
  };
  discard.addEventListener("click", clearRecording);
  fileInput.addEventListener("change", () => {
    // Refuse an oversized file here, before it is uploaded and refused by the server.
    if (fileInput.files[0] && fileInput.files[0].size > 15 * 1024 * 1024) {
      fileInput.value = "";
      previewFile(null);
      status.textContent = "This file is larger than 15 MB and was not selected. Use MP3, M4A or the browser recorder for longer recordings.";
      return;
    }
    previewFile(fileInput.files[0]);
    const consent = form.querySelector("input[name=consent]");
    if (consent) consent.checked = false;
    status.textContent = fileInput.files.length ? "Recording selected. Listen, confirm processing below, then transcribe." : "No recording selected.";
  });
  const capable = Boolean(window.MediaRecorder && navigator.mediaDevices?.getUserMedia);
  if (!capable) {
    start.disabled = true;
    status.textContent = "Microphone recording is unavailable in this browser. Open the private site in a supported secure browser, or upload a recording below.";
  }
  start.addEventListener("click", async () => {
    if (audioBusy) return;
    if (audioUnsaved) { status.textContent = "Transcribe or discard the current recording before starting another."; return; }
    const attempt = ++generation;
    start.disabled = true;
    fileInput.disabled = true;
    discard.disabled = false;
    audioBusy = true;
    recordingFailed = false;
    reachedLimit = false;
    status.textContent = "Allow microphone access to begin recording. Choose Discard to cancel.";
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      if (attempt !== generation) { stream.getTracks().forEach((track) => track.stop()); return; }
      recordingStream = stream;
      const mimeType = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4"].find((value) => MediaRecorder.isTypeSupported(value));
      if (!mimeType) throw new Error("Unsupported recording format");
      recorder = new MediaRecorder(stream, { mimeType });
      const chunks = [];
      let size = 0;
      recorder.addEventListener("dataavailable", (event) => {
        if (attempt !== generation || !event.data.size || recordingFailed) return;
        size += event.data.size;
        if (size > 15 * 1024 * 1024) {
          recordingFailed = true;
          recorder.stop();
          status.textContent = "Recording exceeded the file size limit and was discarded. Record a shorter segment.";
          return;
        }
        chunks.push(event.data);
      });
      recorder.addEventListener("error", () => {
        if (attempt !== generation) return;
        recordingFailed = true;
        release();
        status.textContent = "The recording failed. Discard it and record again, or upload an existing file.";
      });
      recorder.addEventListener("stop", () => {
        if (attempt !== generation) return;
        release();
        if (recordingFailed || !chunks.length) return;
        const blob = new Blob(chunks, { type: mimeType });
        const file = new File([blob], `quillmd-recording.${mimeType.includes("mp4") ? "m4a" : "webm"}`, { type: mimeType });
        try {
          const transfer = new DataTransfer();
          transfer.items.add(file);
          fileInput.files = transfer.files;
          previewFile(file);
          const consent = form.querySelector("input[name=consent]");
          if (consent) consent.checked = false;
          status.textContent = (reachedLimit ? "Recording stopped at the 5-minute limit; anything said after that was not recorded. " : "") + "Recording ready. Listen to it, confirm processing below, then select Transcribe recording.";
        } catch (_) {
          status.textContent = "This browser could not attach the recording. Upload an existing recording instead; nothing was sent.";
        }
      });
      recorder.start(1000);
      stop.disabled = false;
      status.textContent = "Recording. Select Stop when finished. Nothing is sent until you submit this form.";
      stopTimer = setTimeout(() => { if (recorder.state === "recording") { reachedLimit = true; recorder.stop(); } }, 5 * 60 * 1000);
    } catch (error) {
      if (attempt !== generation) return;
      release();
      discard.disabled = true;
      const explanations = {
        NotAllowedError: "Microphone permission was denied. Allow microphone access in this site's browser permissions, then try again or upload a recording.",
        NotFoundError: "No microphone was found. Connect a microphone, then try again or upload a recording.",
        NotReadableError: "The microphone could not be opened. Close other apps using it, then try again or upload a recording."
      };
      status.textContent = explanations[error.name] || "Microphone recording could not start. Check this browser's recording support or upload an existing file.";
    }
  });
  stop.addEventListener("click", () => { if (recorder?.state === "recording") recorder.stop(); });
  window.addEventListener("pagehide", () => { generation += 1; release(); if (audioUrl) URL.revokeObjectURL(audioUrl); });
});

// The mobile drawer changes navigation only. It never changes a user's role,
// session, department, or any clinical form state. Without JS navigation stays visible.
const workspaceShell = document.querySelector('.app-shell');
const workspaceNav = document.getElementById('workspace-navigation');
const navigationToggle = document.querySelector('[data-nav-toggle]');
if (workspaceShell && workspaceNav && navigationToggle) {
  const mobileNavigation = window.matchMedia('(max-width: 740px)');
  const navigationBackdrop = document.querySelector('.navigation-backdrop');
  const mainColumn = document.querySelector('.main-column');
  let navigationOpen = false;
  workspaceShell.classList.add('nav-ready');
  const applyNavigation = (open, restoreFocus = false) => {
    navigationOpen = mobileNavigation.matches && open;
    workspaceShell.classList.toggle('nav-open', navigationOpen);
    navigationToggle.setAttribute('aria-expanded', String(navigationOpen));
    workspaceNav.inert = mobileNavigation.matches && !navigationOpen;
    if (mobileNavigation.matches && !navigationOpen) workspaceNav.setAttribute('aria-hidden', 'true');
    else workspaceNav.removeAttribute('aria-hidden');
    if (navigationBackdrop) navigationBackdrop.hidden = !navigationOpen;
    if (mainColumn) mainColumn.inert = navigationOpen;
    if (navigationOpen) workspaceNav.querySelector('[data-nav-close]').focus();
    else if (restoreFocus) navigationToggle.focus();
  };
  navigationToggle.addEventListener('click', () => applyNavigation(true));
  document.querySelectorAll('[data-nav-close]').forEach((button) => button.addEventListener('click', () => applyNavigation(false, true)));
  workspaceNav.addEventListener('keydown', (event) => {
    if (!navigationOpen) return;
    if (event.key === 'Escape') { event.preventDefault(); applyNavigation(false, true); }
    if (event.key === 'Tab') {
      const controls = [...workspaceNav.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])')].filter((item) => item.getClientRects().length);
      const first = controls[0], last = controls[controls.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
  });
  mobileNavigation.addEventListener('change', () => applyNavigation(false));
  applyNavigation(false);
}

// Search only rows the server has already authorized and rendered; no patient
// identifiers are sent to another endpoint and this is not an all-history search.
const documentSearch = document.querySelector('[data-document-search]');
if (documentSearch) {
  const rows = [...document.querySelectorAll('[data-document-row]')];
  const indexedRows = rows.map(row => ({row, text: row.textContent.toLocaleLowerCase()}));
  document.querySelector('[data-document-search-tools]').hidden = false;
  documentSearch.addEventListener('input', () => {
    const term = documentSearch.value.trim().toLocaleLowerCase();
    let count = 0;
    indexedRows.forEach(({row, text}) => {row.hidden = !text.includes(term); if (!row.hidden) count++;});
    document.querySelector('[data-document-search-result]').textContent = `${count} of ${rows.length} recent documents shown.`;
    document.querySelector('[data-document-search-empty]').hidden = count !== 0;
  });
}

// Keep the compact summary honest while its edit controls are open or closed.
// This changes only a local preview; the exact saved state stays server-bound.
const refreshCompactAnswers = (form) => {
  form.querySelectorAll(".compact-answer").forEach((row) => {
    const input = row.querySelector("textarea[name^='answer_']");
    const decision = row.querySelector("select[name^='decision_']");
    const summary = row.querySelector("[data-saved-answer]");
    if (!input || !summary) return;
    if (!summary.dataset.savedLabel) summary.dataset.savedLabel = summary.textContent;
    const original = input.defaultValue;
    if (input.value === original && (!decision || decision.value === "keep")) {
      summary.textContent = summary.dataset.savedLabel;
    } else {
      summary.textContent = input.value || (decision?.value === "blank" ? "Leave blank — unsaved decision" : "Empty answer — unsaved edit");
    }
  });
};
document.addEventListener("input", (event) => {
  const form = event.target.closest("[data-document-review] form");
  if (form) refreshCompactAnswers(form);
});
document.addEventListener("change", (event) => {
  const form = event.target.closest("[data-document-review] form");
  if (form) refreshCompactAnswers(form);
});
